type IsoGlyphProps = {
  kind: IsoIcon;
  className?: string;
} & Omit<SVGAttributes<SVGSVGElement>, "children" | "viewBox">;

/** Pad a very wide or very narrow drawing into a square so every slot sizes it like the others. */
function squareViewBox(viewBox: string) {
  const [x, y, w, h] = viewBox.split(" ").map(Number);
  const aspect = w / h;
  if (aspect <= 1.08 && aspect >= 0.62) return viewBox;
  const side = Math.max(w, h);
  const nx = x - (side - w) / 2;
  const ny = y - (side - h) / 2;
  return `${nx} ${ny} ${side} ${side}`;
}

export default function IsoGlyph({
  kind,
  className = "",
  ...rest
}: IsoGlyphProps) {
  const icon = ICONS[kind];

  return (
    <svg
      aria-hidden
      viewBox={squareViewBox(icon.viewBox)}
      preserveAspectRatio="xMidYMid meet"
      fill="none"
      overflow="visible"
      className={className}
      {...rest}
    >
      {icon.paths.map((d) => (
        <path key={d} d={d} {...mark} />
      ))}
    </svg>
  );
}
